import tty from 'node:tty';
import { type Stream } from 'stream';

type Options = {
  defaultWidth?: number;
  output?: Stream | typeof process.stdout;
  tty?: typeof tty;
};

export default function cliWidth(options?: Options): number | undefined {
  const opts = normalizeOpts(options);

  if (
    opts.output &&
    'getWindowSize' in opts.output &&
    typeof opts.output.getWindowSize === 'function'
  ) {
    return opts.output.getWindowSize()[0] || opts.defaultWidth;
  }

  if (
    opts.tty &&
    'getWindowSize' in opts.tty &&
    typeof opts.tty.getWindowSize === 'function'
  ) {
    return opts.tty.getWindowSize()[1] || opts.defaultWidth;
  }

  if (opts.output && 'columns' in opts.output) {
    return opts.output.columns as number;
  }

  if (process.env.CLI_WIDTH) {
    const width = parseInt(process.env.CLI_WIDTH, 10);

    if (!isNaN(width) && width !== 0) {
      return width;
    }
  }

  return opts.defaultWidth;
}

function normalizeOpts(options?: Options) {
  const defaultOpts: Options = {
    defaultWidth: 0,
    output: process.stdout,
    tty,
  };

  if (!options) {
    return defaultOpts;
  }

  const optionsWithDefaults: Options = {
    ...defaultOpts,
    ...options,
  };

  return optionsWithDefaults;
}
